"""Describe K12 N8 at author-annotated ST1 tumor border vs other border niches."""
import os
for k in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS'):os.environ.setdefault(k,'4')
import json,base64
from pathlib import Path
import numpy as np,pandas as pd,anndata as ad
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import nbformat
W=Path('/data1/xueshuailin/CCC_Phe/workspace');B=W/'outputs/nsclc_zhencaiwei/ST1_ST5/v3_joint';K=W/'outputs/nsclc_zhencaiwei/ST1_ST5/v3_joint_K12';O=W/'outputs/nsclc_zhencaiwei/ST1_ST5/st1_boundary_k12_n8';O.mkdir(parents=True,exist_ok=True)
q=np.load(K/'predictions.npz');ids=q['cell_ids'].astype(str);sid=q['sample_id'];lab=q['labels'];a=ad.read_h5ad(W/'data/nsclc_zhencaiwei/processed/ST1/ST1_counts.h5ad');obs=a.obs;assert np.array_equal(np.char.add('ST1::',a.obs_names.to_numpy(dtype=str)),ids[sid==0]);assert np.all(sid[:a.n_obs]==0)
bound=obs.Tumor_boundary.astype(str).isin(['Inner 1','Inner 2','Outer 1','Outer 2']).to_numpy();group=lab[:a.n_obs]==7;n8=np.flatnonzero(bound&group);other=np.flatnonzero(bound&~group);assert len(n8)>0;print('N8',len(n8),'other border',len(other),flush=True)
target=Path(json.loads((B/'target_cache.json').read_text())['folder']);comp=np.load(target/'composition.npy',mmap_mode='r');names=sorted(obs['assign.copyKAT'].astype(str).unique());assert comp.shape[1]==len(names);ct=obs['assign.copyKAT'].astype(str).to_numpy();my=obs['assign.curated.Myeloid.inte'].astype(str).to_numpy()
fractions=pd.DataFrame({'cell_type':names,'N8_mean':comp[n8].mean(0),'other_boundary_mean':comp[other].mean(0)});fractions['difference']=fractions.N8_mean-fractions.other_boundary_mean;fractions.to_csv(O/'neighborhood_composition.csv',index=False)
centers=pd.crosstab(pd.Series(np.where(group[bound],'N8','Other boundary'),name='group'),pd.Series(ct[bound],name='center_type'),normalize='index').T;centers.to_csv(O/'center_cell_types.csv')
sub=obs['assign.curated.Myeloid.inte'].astype(str).to_numpy();mt=bound & (ct=='Myeloid');myeloid=pd.crosstab(pd.Series(np.where(group[mt],'N8','Other boundary'),name='group'),pd.Series(sub[mt],name='author_myeloid_subtype'));myeloid.to_csv(O/'myeloid_subtypes_counts.csv');my_frac=myeloid.div(myeloid.sum(axis=1),axis=0);my_frac.to_csv(O/'myeloid_subtypes_fraction.csv')
# Paired names are opportunity-normalized pathway features, not independent data.
# Compare log1p scores within feature; only centers with sender->receiver
# opportunity in each group, requiring 100 supported windows in both.
E=np.load(B/'exposure.npy',mmap_mode='r');M=np.load(B/'exposure_mask.npy',mmap_mode='r');meta=pd.read_csv(B/'exposure_support.csv');A=np.asarray(E[n8],dtype='float32');C=np.asarray(E[other],dtype='float32');ma=np.asarray(M[n8],bool)&np.isfinite(A);mc=np.asarray(M[other],bool)&np.isfinite(C);A=np.log1p(np.maximum(A,0));C=np.log1p(np.maximum(C,0));na=ma.sum(0);nc=mc.sum(0);am=np.where(ma,A,0).sum(0)/np.maximum(na,1);cm=np.where(mc,C,0).sum(0)/np.maximum(nc,1);av=np.where(ma,(A-am)**2,0).sum(0)/np.maximum(na,1);cv=np.where(mc,(C-cm)**2,0).sum(0)/np.maximum(nc,1);d=(am-cm)/np.maximum(np.sqrt((av+cv)/2),.05);results=meta.copy();results['N8_supported']=na;results['other_supported']=nc;results['N8_log1p_mean']=am;results['other_log1p_mean']=cm;results['standardized_difference']=d;results['N8_support_fraction']=na/len(n8);results['other_support_fraction']=nc/len(other);keep=(na>=100)&(nc>=100)&(na/len(n8)>=.1)&(nc/len(other)>=.1);results=results.loc[keep].sort_values('standardized_difference',ascending=False);results.to_csv(O/'pathway_directed_comparison.csv',index=False);logcols=['pathway','sender','receiver','N8_supported','other_supported','N8_log1p_mean','other_log1p_mean','standardized_difference'];top=results.head(20)[logcols];top.to_csv(O/'top_pathways.csv',index=False);print('N8 composition',fractions.to_string(index=False),flush=True);print('N8 myeloid',myeloid.to_string(),flush=True);print('top pathways',top.head(12).to_string(index=False),flush=True)
# Prespecified marker expression within lymphocyte/myeloid cells in the two border groups.
genes=['CXCL9','CXCL10','SPP1','SLPI','HLA-DRA','CD8A','NKG7','GZMB','PRF1','IFNG','FAP','COL1A1'];geneidx=a.var_names.get_indexer(genes);markers=[]
for t in ['Lymphocyte','Myeloid','Fibroblast']:
 for label,ix in [('N8',n8),('Other boundary',other)]:
  rows=ix[ct[ix]==t];denom=np.asarray(obs.nCount_RNA.iloc[rows],dtype=float)
  for gene,j in zip(genes,geneidx):
   if j<0 or not len(rows):continue
   raw=a.X[rows,j];raw=np.asarray(raw.toarray()).ravel() if hasattr(raw,'toarray') else np.asarray(raw).ravel();values=np.log1p(raw*1e4/np.maximum(denom,1));markers.append({'cell_type':t,'group':label,'gene':gene,'n_cells':len(rows),'mean_log1p_CP10k':float(values.mean()),'fraction_detected':float((raw>0).mean())})
pd.DataFrame(markers).to_csv(O/'marker_expression_by_type.csv',index=False)
# Simple spatial and effect display.
xy=np.asarray(a.obsm['spatial_native']);fig,axs=plt.subplots(1,3,figsize=(16,5),layout='constrained');order=np.random.default_rng(42).permutation(len(ct));axs[0].scatter(xy[order,0],xy[order,1],c='#dddddd',s=.25,lw=0,rasterized=True);ix=n8;axs[0].scatter(xy[ix,0],xy[ix,1],c='#d15558',s=.8,lw=0,rasterized=True);axs[0].axis('off');axs[0].set_aspect('equal');axs[0].set_title('ST1 author boundary · N8')
y=np.arange(len(names));axs[1].barh(y-.18,fractions.N8_mean,height=.35,label='N8',color='#cd6566');axs[1].barh(y+.18,fractions.other_boundary_mean,height=.35,label='Other boundary',color='#aab6bb');axs[1].set_yticks(y,names);axs[1].invert_yaxis();axs[1].set_xlabel('Mean distance-weighted composition');axs[1].set_title('Neighborhood composition');axs[1].legend(frameon=False,fontsize=8)
show=top.head(12).iloc[::-1];axs[2].barh(range(len(show)),show.standardized_difference,color='#bd6c69');axs[2].set_yticks(range(len(show)),[f"{r.pathway.replace('Signaling by ','')} · {r.sender} → {r.receiver}" for r in show.itertuples()],fontsize=7);axs[2].set_xlabel('N8 − other border · standardized difference');axs[2].set_title('Directed pathway candidates');fig.savefig(O/'overview.png',dpi=150);plt.close(fig)
metaout={'sample':'ST1','niche':'joint V3/V1 K12 N8 (raw label 7)','boundary':'author Tumor_boundary Inner1/2 and Outer1/2','N8_centers':len(n8),'other_boundary_centers':len(other),'communication_comparison':'log1p opportunity-normalized pathway x sender x receiver features, mean difference divided by pooled within-group SD; >=100 supported centers and >=10% support in each group; descriptive not statistical enrichment','limitations':'same communication inputs helped form cluster; circular descriptive characterization, not independent validation; spatially overlapping windows; one slice; feature opportunity and expression affect scores; two examples do not establish disease causes','converged':False};(O/'protocol.json').write_text(json.dumps(metaout,ensure_ascii=False,indent=2));
nbpath=Path('/home/xueshuailin/CCC_Phe/Cellist_ST1_ST5_Joint_V3.ipynb');n=nbformat.read(nbpath,4);tag='st1_k12_n8_boundary_description';source='''# ST1 边界 N8：组成和通讯\nfrom pathlib import Path\nimport pandas as pd\nfrom IPython.display import display, Image\np=Path('/data1/xueshuailin/CCC_Phe/workspace/outputs/nsclc_zhencaiwei/ST1_ST5/st1_boundary_k12_n8')\ndisplay(Image(filename=str(p/'overview.png'),width=1200))\nprint('邻域组成（距离加权）：')\ndisplay(pd.read_csv(p/'neighborhood_composition.csv').round(3))\nprint('边界中心细胞类型比例：')\ndisplay(pd.read_csv(p/'center_cell_types.csv').round(3))\nprint('作者髓系亚群：中心细胞数量及髓系内部比例：')\ndisplay(pd.read_csv(p/'myeloid_subtypes_counts.csv'));display(pd.read_csv(p/'myeloid_subtypes_fraction.csv').round(3))\nprint('N8 相比 ST1 其他边界 niche 的通讯候选（正值为 N8 高；限制于两组都有足够通讯机会的通路、发送和接收细胞）：')\ndisplay(pd.read_csv(p/'top_pathways.csv').round(3))\nprint('这是描述性比较：通讯输入参与了 niche 划分，邻域互相重叠，不能作为独立验证或显著性检验。')\n''';cell=nbformat.v4.new_code_cell(source,metadata={'tags':[tag]});outputs=[nbformat.v4.new_output('display_data',data={'image/png':base64.b64encode((O/'overview.png').read_bytes()).decode()},metadata={})];txt='ST1 边界 N8 '+str(len(n8))+' 个，其他边界 '+str(len(other))+' 个。\n\n邻域组成：\n'+fractions.round(3).to_string(index=False)+'\n\n中心细胞类型比例：\n'+centers.round(3).to_string()+'\n\n髓系亚群数量：\n'+myeloid.to_string()+'\n\n髓系内部比例：\n'+my_frac.round(3).to_string()+'\n\n高于其他边界的通讯候选：\n'+top.head(15).round(3).to_string(index=False)+'\n\n通讯特征参与聚类，因此仅作描述；不可解释为独立验证。\n';outputs.append(nbformat.v4.new_output('stream',name='stdout',text=txt));cell.outputs=outputs;matches=[i for i,c in enumerate(n.cells) if tag in c.get('metadata',{}).get('tags',[])];
if matches:n.cells[matches[0]]=cell
else:n.cells.append(cell)
nbformat.write(n,nbpath);print('COMPLETE',O,flush=True)
